namespace Game.Input
{
    /// <summary>
    /// ゲーム内で使用する操作識別子。
    ///
    /// 物理的なキーや入力デバイスとは独立して、
    /// ゲーム内の操作を識別するために使用する。
    /// </summary>
    public enum GameInputAction
    {
        #region Common

        /// <summary>
        /// 操作なし。
        /// </summary>
        None = 0,

        #endregion

        #region Movement

        /// <summary>
        /// 上下左右をまとめた2軸移動操作。
        /// </summary>
        Move = 100,

        /// <summary>
        /// 上方向への移動。
        /// </summary>
        MoveUp = 101,

        /// <summary>
        /// 下方向への移動。
        /// </summary>
        MoveDown = 102,

        /// <summary>
        /// 左方向への移動。
        /// </summary>
        MoveLeft = 103,

        /// <summary>
        /// 右方向への移動。
        /// </summary>
        MoveRight = 104,

        #endregion

        #region Gameplay

        /// <summary>
        /// アイテムの使用。
        /// </summary>
        UseItem = 200,

        /// <summary>
        /// サポートキャラクターの召喚。
        /// </summary>
        Summon = 201,

        /// <summary>
        /// ゲームの一時停止。
        /// </summary>
        Pause = 202,

        #endregion

        #region User Interface

        /// <summary>
        /// UI選択方向を表す2軸操作。
        /// </summary>
        Navigate = 300,

        /// <summary>
        /// UIの上方向への移動。
        /// </summary>
        NavigateUp = 301,

        /// <summary>
        /// UIの下方向への移動。
        /// </summary>
        NavigateDown = 302,

        /// <summary>
        /// UIの左方向への移動。
        /// </summary>
        NavigateLeft = 303,

        /// <summary>
        /// UIの右方向への移動。
        /// </summary>
        NavigateRight = 304,

        /// <summary>
        /// 選択項目の決定。
        /// </summary>
        Submit = 305,

        /// <summary>
        /// 選択のキャンセル、前画面への移動。
        /// </summary>
        Cancel = 306,

        /// <summary>
        /// 前のタブへの切り替え。
        /// </summary>
        PreviousTab = 307,

        /// <summary>
        /// 次のタブへの切り替え。
        /// </summary>
        NextTab = 308

        #endregion
    }
}
